<script setup lang="ts">
import { ensureStrings, lazyStrings } from '@/strings';
import { ref, computed, watch } from 'vue';
import { BugIcon, XIcon, MessageSquareIcon, NetworkIcon, FileCodeIcon, HighlighterIcon, ZapOffIcon, ChevronLeftIcon, ChevronRightIcon, EyeIcon, EyeOffIcon, CornerUpRightIcon, CopyIcon, CheckIcon } from 'lucide-vue-next';
import ChatDebugTreeNode from './ChatDebugTreeNode.vue';
import BinaryObjectPreviewModal from './BinaryObjectPreviewModal.vue';
import type { BinaryObjectPreviewItem } from '@/composables/useImagePreview';
import { storageService } from '@/00-storage/service';
import { useRouter } from 'vue-router';
import { useGlobalEvents } from '@/composables/useGlobalEvents';
import type { Chat, MessageBranch, MessageNode } from '@/01-models/types';
import AllowedHtmlView from '@/components/common/AllowedHtmlView.vue';
import { allowedHtml, jsonToHighlightedHtml } from '@/logic/security/allowedHtml';
import { FAKE_LM_ENDPOINT_URL, useFakeLmDebugMode } from '@/features/fake-lm';
import { useSettings } from '@/composables/useSettings';
import { idToRaw, toBinaryObjectId } from '@/01-models/ids';
import type { BinaryObjectId, MessageId } from '@/01-models/ids';
import { inspectDebugImages } from '@/logic/chat-debug-images';
import { getChatBranchIterator } from '@/logic/chat-tree';
import { onUnmounted } from 'vue';

const props = defineProps<{
  show: boolean,
  chat: Readonly<Chat> | undefined,
  activeMessages: ReadonlyArray<MessageNode>,
}>();

const emit = defineEmits<{
  (e: 'close'): void,
  (e: 'enable-fake-lm'): void,
}>();

const router = useRouter();
const { addErrorEvent } = useGlobalEvents();
const { fakeLmDebugModeAvailability } = useFakeLmDebugMode();
const { settings } = useSettings();
const fakeLmDebugModeStatus = computed(() => settings.value.experimental?.fakeLm ?? 'disabled');
const mode = ref<'active' | 'tree' | 'raw'>('active');
const isHighlightEnabled = ref(true);
const isContentCollapsed = ref(false);
const selectedNode = ref<Readonly<MessageNode> | null>(null);
const isTreeMapCollapsed = ref(false);
const rawJsonScope = ref<'full-chat' | 'current-thread'>('full-chat');
const rawJsonCopied = ref(false);
let rawJsonCopyRequestId = 0;

const activeIds = computed(() => new Set(props.activeMessages.map(m => m.id)));
const canEnableFakeLmForChat = computed(() => fakeLmDebugModeAvailability.value === 'available');
const fakeLmButtonTitle = computed(() => {
  if (!canEnableFakeLmForChat.value) {
    return lazyStrings.ChatDebugInspector__fake_lm_is_only_available_in_hosted_builds();
  }

  return lazyStrings.ChatDebugInspector__set_this_chat_to_ollama_and_enable_global_fake_lm_debug_mode({ endpointUrl: FAKE_LM_ENDPOINT_URL });
});

function handleSelectNode({ node }: { node: Readonly<MessageNode> }) {
  selectedNode.value = node;
}

function handleOpenMessage({ messageId }: { messageId: MessageId }) {
  const query = { ...(router.currentRoute.value.query ?? {}) };
  delete query.leaf;
  router.push({ query: { ...query, 'message-id': idToRaw({ id: messageId }) } });
  emit('close');
}

// Resolve only the selected branch; a removed node must not silently select a sibling.
const selectedPath = computed(() => {
  if (!selectedNode.value || !props.chat) return [];
  const path = [...getChatBranchIterator({ chat: { ...props.chat, currentLeafId: selectedNode.value.id } })];
  return path.at(-1)?.id === selectedNode.value.id ? path : [];
});

// Attachment Preview Logic
const previewObjects = ref<BinaryObjectPreviewItem[]>([]);
const previewInitialId = ref<BinaryObjectId | null>(null);

let previewRequest = 0;
watch([() => props.show, mode, () => props.chat, () => selectedNode.value?.id], () => {
  previewRequest += 1; previewObjects.value = []; previewInitialId.value = null;
});
onUnmounted(() => {
  previewRequest += 1;
});

async function handlePreviewAttachment({ binaryObjectId }: { binaryObjectId: BinaryObjectId }) {
  const request = ++previewRequest;
  const allImageIds = new Set<BinaryObjectId>();
  const attachmentImages = new Map<BinaryObjectId, BinaryObjectPreviewItem>();

  // Determine which nodes to scan based on the current mode
  const nodesToScan = (() => {
    const m = mode.value;
    switch (m) {
    case 'tree': return selectedPath.value;
    case 'active': return props.activeMessages;
    case 'raw': return [];
    default: {
      const _ex: never = m;
      return _ex;
    }
    }
  })();

  // Helper to extract IDs from a node
  const extractIds = async ({ node }: { node: MessageNode }): Promise<void> => {
    for (const part of node.parts) {
      if (part.type === 'attachment' && part.attachment.status !== 'missing' && part.attachment.mimeType.startsWith('image/')) {
        const attachment = part.attachment;
        allImageIds.add(attachment.binaryObjectId);
        attachmentImages.set(attachment.binaryObjectId, {
          id: attachment.binaryObjectId,
          name: attachment.originalName,
          mimeType: attachment.mimeType,
          size: attachment.size,
          createdAt: attachment.uploadedAt,
          memoryBlob: (() => {
            switch (attachment.status) {
            case 'memory': return attachment.blob;
            case 'persisted': return undefined;
            default: {
              const unhandled: never = attachment;
              throw new Error(`Unhandled attachment: ${unhandled}`);
            }
            }
          })(),
        });
      }
    }
    const inspection = inspectDebugImages({ message: node });
    for (const { image } of inspection.images) allImageIds.add(toBinaryObjectId({ raw: image.binaryObjectId }));
    for (const details of inspection.errors) {
      addErrorEvent({ source: 'ChatDebugInspector:handlePreviewAttachment', message: await ensureStrings.ChatDebugInspector__failed_to_parse_image_metadata_during_preview_collection(), details });
    }
  };

  // Traverse the relevant nodes
  for (const node of nodesToScan) {
    await extractIds({ node });
  }

  // Ensure the clicked one is in the set
  allImageIds.add(binaryObjectId);

  // Fetch metadata for all found images
  const objects: BinaryObjectPreviewItem[] = [];
  for (const id of allImageIds) {
    const attachment = attachmentImages.get(id);
    if (attachment) {
      objects.push(attachment);
      continue;
    }
    const obj = await storageService.getBinaryObject({ binaryObjectId: id });
    if (request !== previewRequest) return;
    if (obj && obj.mimeType.startsWith('image/')) objects.push({ ...obj, memoryBlob: undefined });
  }

  // Sort by creation date if available, otherwise keep order
  objects.sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));

  if (request === previewRequest && props.show && objects.length > 0) {
    previewObjects.value = objects;
    previewInitialId.value = binaryObjectId;
  }
}

function handleEnableFakeLm() {
  if (!canEnableFakeLmForChat.value) {
    return;
  }

  emit('enable-fake-lm');
}

function handleClose() {
  emit('close');
}

function buildCurrentThreadRoot({ messages }: { messages: ReadonlyArray<MessageNode> }): MessageBranch {
  let items: MessageNode[] = [];

  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message === undefined) {
      continue;
    }

    items = [{
      ...message,
      replies: {
        ...message.replies,
        items,
      },
    }];
  }

  return { items };
}

const rawJsonText = computed(() => {
  const scope = rawJsonScope.value;
  switch (scope) {
  case 'full-chat':
    return JSON.stringify(props.chat, null, 2) ?? '';
  case 'current-thread': {
    if (props.chat === null || props.chat === undefined) {
      return JSON.stringify(props.chat, null, 2) ?? '';
    }

    return JSON.stringify({
      ...props.chat,
      root: buildCurrentThreadRoot({ messages: props.activeMessages }),
    }, null, 2) ?? '';
  }
  default: {
    const _ex: never = scope;
    throw new Error(`Unhandled raw JSON scope: ${_ex}`);
  }
  }
});

watch(
  () => {
    const m = mode.value;
    switch (m) {
    case 'active':
    case 'tree':
      return null;
    case 'raw':
      return rawJsonText.value;
    default: {
      const _ex: never = m;
      throw new Error(`Unhandled mode: ${_ex}`);
    }
    }
  },
  () => {
    rawJsonCopyRequestId += 1;
    rawJsonCopied.value = false;
  },
);

const rawJsonOutput = computed(() => {
  const m = mode.value;
  switch (m) {
  case 'active':
  case 'tree':
    return allowedHtml``;
  case 'raw':
    return jsonToHighlightedHtml({
      json: rawJsonText.value,
      highlight: isHighlightEnabled.value,
      keyStyle: 'raw',
    });
  default: {
    const _ex: never = m;
    throw new Error(`Unhandled mode: ${_ex}`);
  }
  }
});

async function handleCopyRawJson(): Promise<void> {
  const json = rawJsonText.value;
  const requestId = rawJsonCopyRequestId + 1;
  rawJsonCopyRequestId = requestId;
  rawJsonCopied.value = false;

  try {
    await navigator.clipboard.writeText(json);
    if (requestId !== rawJsonCopyRequestId) {
      return;
    }

    rawJsonCopied.value = true;
    setTimeout(() => {
      if (requestId === rawJsonCopyRequestId) {
        rawJsonCopied.value = false;
      }
    }, 2000);
  } catch (error) {
    if (requestId === rawJsonCopyRequestId) {
      rawJsonCopied.value = false;
    }
    console.error('Failed to copy Chat Inspector JSON:', error);
  }
}


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/1fc98b1e0764836790457dde9d75f53dd245a646ec1690c6f5417619af93b907.js";
import "virtual:naidan-tailwind-css-module/5682c18a7b6267c14b0917dfe87f01f5e88002052bfa2b14851ab01b96abf44e.js";
import "virtual:naidan-tailwind-css-module/6448d338f24abe862d718c8ddfb0634fb5fda3965fae7ca20ccb397d234f9954.js";
import "virtual:naidan-tailwind-css-module/b521e235b4efb22b5e330a04e4d91f8c39b2c049a3cdff309119a66c11397e7d.js";
import "virtual:naidan-tailwind-css-module/bd5518240d103fdc790d66490d27072253d242a50b0873716ccac17cc344fd2b.js";
import "virtual:naidan-tailwind-css-module/db84e1284369be57539814f1c791d4395e9a519706bee5bf0bbf2b0c0393d3fc.js";
