              :disabled="!canEnableFakeLmForChat"
              :title="fakeLmButtonTitle"
              data-testid="chat-inspector-enable-fake-lm"
            >
              <BugIcon tw-class="w-4 h-4" />
              <span>{{ lazyStrings.ChatDebugInspector__fake_lm() }}</span>
              <span
